/**
 * IPC Server
 *
 * Unix domain socket server that accepts connections from hook scripts and
 * other short-lived processes. Each connection sends a single newline-
 * delimited JSON message, receives a single JSON response, and closes.
 *
 * Design decisions:
 * - One message per connection (request/response, then close) keeps the
 *   protocol simple and avoids half-open socket edge cases.
 * - Stale socket files from a previous crash are removed on startup so the
 *   server can always bind cleanly.
 * - Idle connections are closed after 5 seconds to prevent resource leaks.
 * - All errors are logged and swallowed; the server never throws from within
 *   connection handlers.
 */

import * as net from 'node:net';
import { mkdirSync, existsSync, unlinkSync, chmodSync } from 'node:fs';
import { dirname, join } from 'node:path';

import type { IPCMessage, IPCResponse } from './protocol.js';
import { validateIPCMessage } from './protocol.js';
import { createLogger } from '../logger.js';
import { toErrorMessage, safeJsonParse } from '../utils.js';
import { IPCError } from '../errors.js';

const logger = createLogger('ipc-server');

/** Milliseconds before an idle connection is forcibly closed. */
const CONNECTION_TIMEOUT_MS = 5_000;

/** Maximum IPC message size in bytes. Messages exceeding this limit are rejected. */
const MAX_MESSAGE_SIZE = 1_048_576; // 1 MB

/** Maximum messages per second before rate limiting kicks in. */
const RATE_LIMIT_MAX = 100;

/** Sliding window duration for rate limiting in milliseconds. */
const RATE_LIMIT_WINDOW_MS = 1_000;

/**
 * Envelope returned by handlers that need write-result confirmation.
 * The `holdId` is passed back to the write-result callback after the socket write.
 */
export interface ResponseEnvelope {
  response: IPCResponse;
  holdId?: string;
}

/**
 * Callback invoked for every well-formed IPC message received.
 * Must return a {@link IPCResponse} or {@link ResponseEnvelope} (or a Promise resolving to one).
 */
export type MessageHandler = (msg: IPCMessage) => Promise<IPCResponse | ResponseEnvelope>;

/**
 * Callback invoked after every socket write attempt.
 * `success` is true when the write succeeded, false when it threw.
 */
export type WriteResultCallback = (holdId: string, success: boolean) => void;

function isResponseEnvelope(r: IPCResponse | ResponseEnvelope): r is ResponseEnvelope {
  return r !== null && typeof r === 'object' && 'response' in r && !('status' in r);
}

/**
 * Unix domain socket server for hook ↔ runtime engine communication.
 *
 * @example
 * ```ts
 * const server = new IPCServer('.goodvibes/gv-abc12345/runtime.sock');
 * server.onMessage(async (msg) => {
 *   return { id: msg.id, status: 'ok', data: { kind: 'ack' } };
 * });
 * await server.listen();
 * // ... later ...
 * await server.close();
 * ```
 */
export class IPCServer {
  /** The underlying Node.js TCP/socket server. */
  private server: net.Server | null = null;

  /** Absolute path to the Unix domain socket file. */
  private readonly socketPath: string;

  /** Application-level handler for decoded IPC messages. */
  private handler: MessageHandler | null = null;

  /** Set of all currently open client sockets (for clean shutdown). */
  private readonly connections: Set<net.Socket> = new Set();

  /** Optional callback invoked after each socket write with write success/failure. */
  private writeResultCallback?: WriteResultCallback;

  /** Tracks in-flight holdIds per socket for async write confirmation and error recovery. */
  private readonly inFlightHolds = new WeakMap<net.Socket, string>();

  /** Circular buffer of recent message timestamps for O(1) rate limiting. */
  private readonly recentMessages: number[] = new Array(RATE_LIMIT_MAX).fill(0) as number[];
  /** Next write position in the circular buffer. */
  private msgHead = 0;
  /** Current count of entries in the buffer. */
  private msgCount = 0;

  /**
   * @param socketPath - Absolute path for the Unix domain socket file.
   *   The parent directory is created automatically if it does not exist.
   */
  constructor(socketPath: string) {
    this.socketPath = socketPath;
  }

  // ─── Public API ───────────────────────────────────────────────────────────

  /**
   * Register the message handler.
   *
   * Must be called before {@link listen}. Only one handler is supported;
   * subsequent calls replace the previous one.
   *
   * @param handler - Async function that receives a decoded {@link IPCMessage}
   *   and returns an {@link IPCResponse}.
   */
  onMessage(handler: MessageHandler): void {
    this.handler = handler;
  }

  /**
   * Register a callback to be notified after each socket write attempt.
   *
   * Used by the hold-and-release pattern: on success, call `releaseHold(holdId)`;
   * on failure, call `reEnqueueHold(holdId)` to recover the directives.
   *
   * @param cb - Callback receiving the holdId and write success flag.
   */
  setWriteResultCallback(cb: WriteResultCallback): void {
    this.writeResultCallback = cb;
  }

  /**
   * Start listening for incoming connections on the configured socket path.
   *
   * Steps:
   * 1. Create the socket directory if it does not exist.
   * 2. Remove any stale socket file left by a previous process.
   * 3. Bind and start listening.
   *
   * @throws If the server cannot bind to the socket path.
   */
  async listen(): Promise<void> {
    // 1. Ensure parent directory exists with restricted permissions
    const dir = dirname(this.socketPath);
    mkdirSync(dir, { recursive: true, mode: 0o700 });
    chmodSync(dir, 0o700);

    // 2. Remove stale socket file if present
    if (existsSync(this.socketPath)) {
      try {
        unlinkSync(this.socketPath);
        logger.debug('Removed stale socket file', { path: this.socketPath });
      } catch (err) {
        logger.warn('Could not remove stale socket file', {
          path: this.socketPath,
          err: toErrorMessage(err),
        });
      }
    }

    // 3. Create and start the server
    this.server = net.createServer((socket) => this.handleConnection(socket));

    this.server.on('error', (err) => {
      logger.error('IPC server error', { err: err.message });
    });

    return new Promise<void>((resolve, reject) => {
      const srv = this.server;
      if (!srv) {
        reject(new IPCError('IPC server was not created'));
        return;
      }
      srv.once('error', reject);
      srv.listen(this.socketPath, () => {
        // Restrict socket file to owner-only access
        chmodSync(this.socketPath, 0o600);
        logger.info('IPC server listening', { path: this.socketPath });
        // Remove the startup error listener now that we have bound successfully
        srv.removeListener('error', reject);
        resolve();
      });
    });
  }

  /**
   * Stop accepting new connections and close all existing ones.
   *
   * Destroys all tracked sockets immediately, then waits for the server
   * to finish closing before resolving.
   */
  async close(): Promise<void> {
    logger.info('Closing IPC server', {
      path: this.socketPath,
      connections: this.connections.size,
    });

    // Re-enqueue any in-flight held directives before destroying sockets
    for (const socket of this.connections) {
      const holdId = this.inFlightHolds.get(socket);
      if (holdId && this.writeResultCallback) {
        this.inFlightHolds.delete(socket);
        this.writeResultCallback(holdId, false);
      }
    }

    // Destroy all open client connections
    for (const socket of this.connections) {
      socket.destroy();
    }
    this.connections.clear();

    // Close the server and remove the socket file
    return new Promise<void>((resolve) => {
      if (!this.server) {
        resolve();
        return;
      }
      const srv = this.server;
      this.server = null;
      srv.close(() => {
        this.removeSocketFile();
        logger.info('IPC server closed');
        resolve();
      });
    });
  }

  /**
   * The number of currently open client connections.
   */
  get clientCount(): number {
    return this.connections.size;
  }

  /**
   * The absolute path of the Unix domain socket file.
   */
  getSocketPath(): string {
    return this.socketPath;
  }

  // ─── Private helpers ───────────────────────────────────────────────────────

  /**
   * Handle a new incoming client connection.
   *
   * Reads a complete newline-delimited JSON message, dispatches it to the
   * handler, writes the JSON response, then closes the socket.
   *
   * @param socket - The accepted client socket.
   */
  private handleConnection(socket: net.Socket): void {
    this.connections.add(socket);

    // Rate limit check — reject if too many messages in the sliding window
    if (this.isRateLimited()) {
      logger.warn('IPC rate limit exceeded — rejecting connection', {
        limit: RATE_LIMIT_MAX,
        window_ms: RATE_LIMIT_WINDOW_MS,
      });
      const rateLimitResponse: IPCResponse = {
        id: 'rate_limited',
        status: 'error',
        error: `Rate limit exceeded: max ${RATE_LIMIT_MAX} messages per second`,
      };
      try {
        socket.end(JSON.stringify(rateLimitResponse) + '\n', 'utf-8');
      } catch {
        socket.destroy();
      }
      this.connections.delete(socket);
      return;
    }
    this.recordMessage();

    logger.debug('IPC client connected', { connections: this.connections.size });

    // Idle connection timeout — declared before event handlers so all closures
    // capture the same binding. Assigned immediately below.
    let idleTimer: ReturnType<typeof setTimeout>;

    socket.once('close', () => {
      clearTimeout(idleTimer);
      this.connections.delete(socket);
      logger.debug('IPC client disconnected', { connections: this.connections.size });
    });

    socket.on('error', (err) => {
      clearTimeout(idleTimer);
      logger.warn('IPC socket error', { err: err.message });
      // Re-enqueue any in-flight held directives so they are not lost on socket error
      const holdId = this.inFlightHolds.get(socket);
      if (holdId && this.writeResultCallback) {
        this.inFlightHolds.delete(socket);
        this.writeResultCallback(holdId, false);
      }
      this.connections.delete(socket);
      socket.destroy();
    });

    // Start the idle timeout. idleTimer binding is shared with all event handlers above.
    idleTimer = setTimeout(() => {
      logger.warn('IPC connection timed out — closing', { timeout_ms: CONNECTION_TIMEOUT_MS });
      socket.destroy();
    }, CONNECTION_TIMEOUT_MS);

    const chunks: Buffer[] = [];
    let rawBytes = 0;

    socket.on('data', (chunk: Buffer) => {
      rawBytes += chunk.length; // chunk is Buffer; .length is bytes

      if (rawBytes > MAX_MESSAGE_SIZE) {
        logger.warn('IPC message size limit exceeded — closing connection', {
          size_bytes: rawBytes,
          max_bytes: MAX_MESSAGE_SIZE,
        });
        socket.destroy();
        return;
      }

      // Check for newline in the incoming chunk before buffering
      const newlinePos = chunk.indexOf(0x0a); // 0x0a = '\n'
      if (newlinePos === -1) {
        // No newline yet — buffer the whole chunk and wait for more data
        chunks.push(chunk);
        return;
      }

      // Message complete — push the portion up to (not including) the newline
      chunks.push(chunk.subarray(0, newlinePos));

      // Decode once via Buffer.concat — O(n) instead of O(n^2)
      const line = Buffer.concat(chunks).toString('utf-8');

      // Cancel idle timer and stop collecting data
      clearTimeout(idleTimer);
      socket.pause();

      this.processMessage(socket, line);
    });
  }

  /**
   * Parse and dispatch a raw JSON line, then write the response.
   *
   * @param socket - The client socket to write the response to.
   * @param line   - Raw JSON string (without the trailing newline).
   */
  private processMessage(socket: net.Socket, line: string): void {
    let message: IPCMessage;
    try {
      const parsed: unknown = safeJsonParse<unknown>(line, null);
      if (!validateIPCMessage(parsed)) {
        logger.warn('IPC message failed schema validation — dropping', {
          type: typeof parsed === 'object' && parsed !== null
            ? (parsed as Record<string, unknown>)['type']
            : typeof parsed,
        });
        const validationErrorResponse: IPCResponse = {
          id:
            typeof parsed === 'object' && parsed !== null
              ? String((parsed as Record<string, unknown>)['id'] ?? 'unknown')
              : 'unknown',
          status: 'error',
          error: 'Invalid message schema',
        };
        this.writeResponse(socket, validationErrorResponse);
        return;
      }
      message = parsed;
    } catch {
      // safeJsonParse does not throw; this catch is a safety net only.
      return;
    }

    if (!this.handler) {
      logger.warn('No IPC message handler registered', { msg_type: message.type });
      const noHandlerResponse: IPCResponse = {
        id: message.id,
        status: 'error',
        error: 'No handler registered',
      };
      this.writeResponse(socket, noHandlerResponse);
      return;
    }

    logger.debug('Dispatching IPC message', { id: message.id, type: message.type });

    this.handler(message)
      .then((result) => {
        if (isResponseEnvelope(result)) {
          this.writeResponse(socket, result.response, result.holdId);
        } else {
          this.writeResponse(socket, result);
        }
      })
      .catch((err) => {
        logger.error('IPC handler threw an error', {
          id: message.id,
          err: toErrorMessage(err),
        });
        const errResponse: IPCResponse = {
          id: message.id,
          status: 'error',
          error: toErrorMessage(err),
        };
        this.writeResponse(socket, errResponse);
      });
  }

  /**
   * Serialise and write an {@link IPCResponse} to the client socket, then
   * close the socket half (FIN).
   *
   * @param socket   - The client socket.
   * @param response - The response to send.
   */
  private writeResponse(socket: net.Socket, response: IPCResponse, holdId?: string): void {
    const payload = JSON.stringify(response) + '\n';
    if (holdId) {
      this.inFlightHolds.set(socket, holdId);
    }
    try {
      socket.end(payload, 'utf-8', () => {
        // Async write confirmation — data accepted by kernel
        if (holdId && this.writeResultCallback) {
          this.inFlightHolds.delete(socket);
          this.writeResultCallback(holdId, true);
        }
      });
    } catch (err) {
      logger.warn('Failed to write IPC response', {
        id: response.id,
        err: toErrorMessage(err),
      });
      if (holdId && this.writeResultCallback) {
        this.inFlightHolds.delete(socket);
        this.writeResultCallback(holdId, false);
      }
      socket.destroy();
    }
  }

  /**
   * Check if the current message rate exceeds the limit.
   */
  private isRateLimited(): boolean {
    if (this.msgCount < RATE_LIMIT_MAX) return false;
    // Buffer is full — check if the oldest entry is within the window
    const oldest = this.recentMessages[(this.msgHead - this.msgCount + RATE_LIMIT_MAX) % RATE_LIMIT_MAX];
    return (Date.now() - oldest) < RATE_LIMIT_WINDOW_MS;
  }

  /**
   * Record a message timestamp and prune old entries.
   */
  private recordMessage(): void {
    this.recentMessages[this.msgHead] = Date.now();
    this.msgHead = (this.msgHead + 1) % RATE_LIMIT_MAX;
    if (this.msgCount < RATE_LIMIT_MAX) this.msgCount++;
  }

  /**
   * Remove the socket file from the filesystem, ignoring errors.
   */
  private removeSocketFile(): void {
    try {
      if (existsSync(this.socketPath)) {
        unlinkSync(this.socketPath);
        logger.debug('Socket file removed', { path: this.socketPath });
      }
    } catch (err) {
      logger.warn('Could not remove socket file', {
        path: this.socketPath,
        err: toErrorMessage(err),
      });
    }
  }
}
